export const BLOCKS = [];
export const BLOCK_IDS = {};

for (const d of defs) {
  const tiles = d.tiles || {};
  const b = {
    ...d,
    solid: d.kind === 'solid',
    opaque: d.render === 'opaque' || d.render === 'cutout',
    liquid: d.kind === 'water',
    plant: d.kind === 'plant',
    tiles: {
      top: tiles.top ?? tiles.all ?? 0,
      bottom: tiles.bottom ?? tiles.all ?? 0,
      side: tiles.side ?? tiles.all ?? 0,
    },
    color: d.color || [0.5, 0.5, 0.5],
  };
  BLOCKS[b.id] = b;
  BLOCK_IDS[b.key] = b.id;
}

