594:         const sx = Math.min(TILE_SIZE - 1, Math.max(0, cx - PAD));
595:         const sy = Math.min(TILE_SIZE - 1, Math.max(0, cy - PAD));
596:         const si = (sy * TILE_SIZE + sx) * 4;
597:         const di = ((row * CELL + cy) * px + (col * CELL + cx)) * 4;
598:         albedoData[di] = colors[si];
599:         albedoData[di + 1] = colors[si + 1];
600:         albedoData[di + 2] = colors[si + 2];
601:         albedoData[di + 3] = colors[si + 3];
602:         if (cx >= PAD && cx < PAD + TILE_SIZE && cy >= PAD && cy < PAD + TILE_SIZE) {
603:           const rough = roughs[(cy - PAD) * TILE_SIZE + (cx - PAD)];
604:           roughData[di] = roughData[di + 1] = roughData[di + 2] = rough * 255;
605:           roughData[di + 3] = 255;
606:         } else {
607:           const sxr = Math.min(TILE_SIZE - 1, Math.max(0, cx - PAD));
608:           const syr = Math.min(TILE_SIZE - 1, Math.max(0, cy - PAD));
609:           const rough = roughs[syr * TILE_SIZE + sxr];
610:           roughData[di] = roughData[di + 1] = roughData[di + 2] = rough * 255;
611:           roughData[di + 3] = 255;
612:         }
613:         if (cx < PAD || cx >= PAD + TILE_SIZE || cy < PAD || cy >= PAD + TILE_SIZE) {
614:           const nx2 = Math.min(TILE_SIZE - 1, Math.max(0, cx - PAD));
615:           const ny2 = Math.min(TILE_SIZE - 1, Math.max(0, cy - PAD));
616:           const ni = ((row * CELL + PAD + ny2) * px + (col * CELL + PAD + nx2)) * 4;
617:           normalData[di] = normalData[ni];
618:           normalData[di + 1] = normalData[ni + 1];
619:           normalData[di + 2] = normalData[ni + 2];
