638: export function buildAtlases(maxAnisotropy = 4) {
639:   const { albedoData, normalData, roughData } = buildAtlasData();
640:   const albedoCanvas = dataToCanvas(albedoData, ATLAS_SIZE);
641:   const normalCanvas = dataToCanvas(normalData, ATLAS_SIZE);
642:   const roughCanvas = dataToCanvas(roughData, ATLAS_SIZE);
643: 
644:   const mk = (canvas, srgb) => {
645:     const tex = new THREE.CanvasTexture(canvas);
646:     tex.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
647:     tex.wrapS = tex.wrapT = THREE.ClampToEdgeWrapping;
648:     tex.minFilter = THREE.LinearMipmapLinearFilter;
649:     tex.magFilter = THREE.LinearFilter;
650:     tex.generateMipmaps = true;
651:     tex.anisotropy = Math.max(1, Math.min(8, maxAnisotropy));
652:     tex.needsUpdate = true;
653:     return tex;
654:   };
655: 
656:   return {
657:     albedo: mk(albedoCanvas, true),
658:     normal: mk(normalCanvas, false),
659:     roughness: mk(roughCanvas, false),
660:     albedoCanvas,
661:     normalCanvas,
662:     roughCanvas,
663:     atlasSize: ATLAS_SIZE,
664:   };
