683: // Isometric block icon for the HUD/inventory, composed from atlas tiles.
684: export function makeBlockIcon(defOrId, size = 64) {
685:   const def = typeof defOrId === 'number' ? getBlockDef(defOrId) : defOrId;
686:   const key = `${def.id}:${size}`;
687:   if (iconCache.has(key)) return iconCache.get(key);
688:   const atlas = window.__terravistaAtlas;
689:   const canvas = document.createElement('canvas');
690:   canvas.width = size;
691:   canvas.height = size;
692:   if (!atlas) return canvas;
693:   const ctx = canvas.getContext('2d');
694:   const src = atlas.albedoCanvas;
695:   const col = (tile) => tile % ATLAS_COLS;
696:   const row = (tile) => Math.floor(tile / ATLAS_COLS);
697:   const crop = (tile) => {
698:     const c = document.createElement('canvas');
699:     c.width = TILE_SIZE; c.height = TILE_SIZE;
700:     c.getContext('2d').drawImage(src, col(tile) * CELL + PAD, row(tile) * CELL + PAD, TILE_SIZE, TILE_SIZE, 0, 0, TILE_SIZE, TILE_SIZE);
701:     return c;
702:   };
703:   const top = crop(def.tiles.top);
704:   const side = crop(def.tiles.side);
705: 
706:   const s = size;
707:   const cx = s / 2, cy = s * 0.5;
708:   const w = s * 0.42, h = s * 0.235;
709:   ctx.imageSmoothingEnabled = true;
710:   // top face
711:   ctx.save();
712:   ctx.translate(cx, cy - h * 1.55);
713:   ctx.transform(1, 0.5, -1, 0.5, 0, 0);
714:   ctx.globalAlpha = 1;
715:   ctx.drawImage(top, 0, 0, w, h);
716:   ctx.restore();
717:   // left face (darker)
718:   ctx.save();
719:   ctx.translate(cx, cy - h * 1.05);
720:   ctx.transform(1, 0.5, 0, 1, 0, 0);
721:   ctx.drawImage(side, 0, 0, w, h * 2.05);
722:   ctx.globalCompositeOperation = 'source-atop';
723:   ctx.fillStyle = 'rgba(0,0,0,0.20)';
724:   ctx.fillRect(0, 0, w, h * 2.1);
725:   ctx.restore();
726:   // right face (lighter)
727:   ctx.save();
728:   ctx.translate(cx, cy - h * 0.54);
729:   ctx.transform(1, 0.5, 0, 1, 0, 0);
730:   ctx.drawImage(side, w, 0, -w, h * 2.05);
731:   ctx.globalCompositeOperation = 'source-atop';
732:   ctx.fillStyle = 'rgba(255,255,255,0.05)';
733:   ctx.fillRect(0, 0, w, h * 2.1);
734:   ctx.restore();
735: 
736:   iconCache.set(key, canvas);
737:   return canvas;
