740: export function averageTileColor(tile) {
741:   const atlas = window.__terravistaAtlas;
742:   if (!atlas) return [0.5, 0.5, 0.5];
743:   const image = atlas.albedoCanvas.getContext('2d').getImageData(
744:     (tile % ATLAS_COLS) * CELL + PAD, Math.floor(tile / ATLAS_COLS) * CELL + PAD, TILE_SIZE, TILE_SIZE
745:   ).data;
746:   let r = 0, g = 0, b = 0, n = 0;
747:   for (let i = 0; i < image.length; i += 16) {
748:     if (image[i + 3] > 20) { r += image[i]; g += image[i + 1]; b += image[i + 2]; n++; }
749:   }
750:   if (!n) return [0.5, 0.5, 0.5];
751:   return [r / n / 255, g / n / 255, b / n / 255];
752: }
