30: // Tileable value noise. u,v in [0,1); freq is integer lattice count.
31: function vnoise(u, v, freq, seed) {
32:   const x = u * freq, y = v * freq;
33:   const x0 = Math.floor(x), y0 = Math.floor(y);
34:   const fx = fade(x - x0), fy = fade(y - y0);
35:   const i0 = ((x0 % freq) + freq) % freq;
36:   const j0 = ((y0 % freq) + freq) % freq;
37:   const i1 = (i0 + 1) % freq;
38:   const j1 = (j0 + 1) % freq;
39:   const a = ihash(i0, j0, seed), b = ihash(i1, j0, seed);
40:   const c = ihash(i0, j1, seed), d = ihash(i1, j1, seed);
41:   return mix(mix(a, b, fx), mix(c, d, fx), fy);
