44: function fbmTile(u, v, baseFreq, oct, seed, gain = 0.5) {
45:   let sum = 0, amp = 1, norm = 0, f = baseFreq;
46:   for (let i = 0; i < oct; i++) {
47:     sum += vnoise(u, v, f, seed + i * 37) * amp;
48:     norm += amp;
49:     amp *= gain;
50:     f *= 2;
51:   }
52:   return sum / norm;
