57:   for (let i = 0; i < oct; i++) {
58:     let n = 1 - Math.abs(vnoise(u, v, f, seed + i * 11) * 2 - 1);
59:     n *= n;
60:     sum += n * amp * prev;
61:     norm += amp;
62:     prev = n;
63:     amp *= 0.5;
64:     f *= 2;
65:   }
