69: function voronoiTile(u, v, cells, seed) {
70:   const x = u * cells, y = v * cells;
71:   const ci = Math.floor(x), cj = Math.floor(y);
72:   let best = 1e9, second = 1e9, id = 0;
73:   for (let dj = -1; dj <= 1; dj++) {
74:     for (let di = -1; di <= 1; di++) {
75:       const gi = ci + di, gj = cj + dj;
76:       const wi = ((gi % cells) + cells) % cells;
77:       const wj = ((gj % cells) + cells) % cells;
78:       const px = gi + 0.15 + ihash(wi, wj, seed) * 0.7;
79:       const py = gj + 0.15 + ihash(wi, wj, seed + 91) * 0.7;
80:       const d = (x - px) * (x - px) + (y - py) * (y - py);
81:       if (d < best) { second = best; best = d; id = wi * 31 + wj; }
82:       else if (d < second) second = d;
83:     }
84:   }
85:   return { d: Math.sqrt(best), edge: Math.sqrt(second) - Math.sqrt(best), id: ihash(id, 7, seed) };
86: }
