541: function buildAtlasData() {
542:   const px = ATLAS_SIZE;
543:   const albedoData = new Uint8ClampedArray(px * px * 4);
544:   const normalData = new Uint8ClampedArray(px * px * 4);
545:   const roughData = new Uint8ClampedArray(px * px * 4);
546: 
547:   for (let tile = 0; tile < 64; tile++) {
548:     const col = tile % ATLAS_COLS;
549:     const row = Math.floor(tile / ATLAS_COLS);
550:     const painter = P[tile];
551:     const colors = new Uint8ClampedArray(TILE_SIZE * TILE_SIZE * 4);
552:     const heights = new Float32Array(TILE_SIZE * TILE_SIZE);
553:     const roughs = new Float32Array(TILE_SIZE * TILE_SIZE);
554: 
555:     for (let y = 0; y < TILE_SIZE; y++) {
556:       for (let x = 0; x < TILE_SIZE; x++) {
557:         const u = (x + 0.5) / TILE_SIZE;
558:         const v = (y + 0.5) / TILE_SIZE;
559:         const out = painter(u, v);
560:         const i = y * TILE_SIZE + x;
561:         colors[i * 4] = out.c[0];
562:         colors[i * 4 + 1] = out.c[1];
563:         colors[i * 4 + 2] = out.c[2];
564:         colors[i * 4 + 3] = Math.round(clamp01(out.a) * 255);
565:         heights[i] = out.h;
566:         roughs[i] = out.r;
567:       }
568:     }
569: 
570:     // Normals from the height field (tangent space, +Y up).
571:     const strength = 7.5;
572:     for (let y = 0; y < TILE_SIZE; y++) {
573:       for (let x = 0; x < TILE_SIZE; x++) {
574:         const xm = x > 0 ? x - 1 : x, xp = x < TILE_SIZE - 1 ? x + 1 : x;
575:         const ym = y > 0 ? y - 1 : y, yp = y < TILE_SIZE - 1 ? y + 1 : y;
576:         const hL = heights[y * TILE_SIZE + xm], hR = heights[y * TILE_SIZE + xp];
577:         const hU = heights[ym * TILE_SIZE + x], hD = heights[yp * TILE_SIZE + x];
578:         let nx = -(hR - hL) * strength;
579:         let ny = (hD - hU) * strength;
580:         let nz = 1;
581:         const len = Math.sqrt(nx * nx + ny * ny + nz * nz);
582:         nx /= len; ny /= len; nz /= len;
583:         const i = (y * TILE_SIZE + x) * 4;
584:         normalData[(row * CELL + PAD + y) * px * 4 + (col * CELL + PAD + x) * 4] = (nx * 0.5 + 0.5) * 255;
585:         normalData[(row * CELL + PAD + y) * px * 4 + (col * CELL + PAD + x) * 4 + 1] = (ny * 0.5 + 0.5) * 255;
586:         normalData[(row * CELL + PAD + y) * px * 4 + (col * CELL + PAD + x) * 4 + 2] = (nz * 0.5 + 0.5) * 255;
587:         normalData[(row * CELL + PAD + y) * px * 4 + (col * CELL + PAD + x) * 4 + 3] = 255;
588:       }
589:     }
590: 
591:     // Gutter-replicated albedo/roughness/normal for clean mipmaps.
592:     for (let cy = 0; cy < CELL; cy++) {
593:       for (let cx = 0; cx < CELL; cx++) {
594:         const sx = Math.min(TILE_SIZE - 1, Math.max(0, cx - PAD));
595:         const sy = Math.min(TILE_SIZE - 1, Math.max(0, cy - PAD));
596:         const si = (sy * TILE_SIZE + sx) * 4;
597:         const di = ((row * CELL + cy) * px + (col * CELL + cx)) * 4;
598:         albedoData[di] = colors[si];
599:         albedoData[di + 1] = colors[si + 1];
600:         albedoData[di + 2] = colors[si + 2];
601:         albedoData[di + 3] = colors[si + 3];
602:         if (cx >= PAD && cx < PAD + TILE_SIZE && cy >= PAD && cy < PAD + TILE_SIZE) {
603:           const rough = roughs[(cy - PAD) * TILE_SIZE + (cx - PAD)];
604:           roughData[di] = roughData[di + 1] = roughData[di + 2] = rough * 255;
605:           roughData[di + 3] = 255;
606:         } else {
607:           const sxr = Math.min(TILE_SIZE - 1, Math.max(0, cx - PAD));
608:           const syr = Math.min(TILE_SIZE - 1, Math.max(0, cy - PAD));
609:           const rough = roughs[syr * TILE_SIZE + sxr];
610:           roughData[di] = roughData[di + 1] = roughData[di + 2] = rough * 255;
611:           roughData[di + 3] = 255;
612:         }
613:         if (cx < PAD || cx >= PAD + TILE_SIZE || cy < PAD || cy >= PAD + TILE_SIZE) {
614:           const nx2 = Math.min(TILE_SIZE - 1, Math.max(0, cx - PAD));
615:           const ny2 = Math.min(TILE_SIZE - 1, Math.max(0, cy - PAD));
616:           const ni = ((row * CELL + PAD + ny2) * px + (col * CELL + PAD + nx2)) * 4;
617:           normalData[di] = normalData[ni];
618:           normalData[di + 1] = normalData[ni + 1];
619:           normalData[di + 2] = normalData[ni + 2];
620:           normalData[di + 3] = 255;
621:         }
622:       }
623:     }
624:   }
625: 
626:   return { albedoData, normalData, roughData };
627: }
