629: function dataToCanvas(data, size) {
630:   const canvas = document.createElement('canvas');
631:   canvas.width = size;
632:   canvas.height = size;
633:   const ctx = canvas.getContext('2d');
634:   ctx.putImageData(new ImageData(data, size, size), 0, 0);
635:   return canvas;
636: }
