125:   for (let y = 0; y < WORLD_HEIGHT; y++) for (let z = 0; z < 16; z++) for (let x = 0; x < 16; x++) {
126:     const id = c.blocks[(y << 8) | (z << 4) | x]; if (!id) continue;
127:     const def = BLOCKS[id];
128:     if (def.plant) { pushPlant(plants, x, y, z, def.tiles.all ?? def.tiles.side); continue; }
129:     const out = id === BLOCK_IDS.water || def.render === 'glass' ? transparent : opaque;
130:     for (const face of FACE_DATA) {
131:       const other = getBlock(cx * 16 + x + face.n[0], y + face.n[1], cz * 16 + z + face.n[2]);
132:       if (visibleAgainst(id, other)) pushFace(out, x, y, z, face, def.tiles[face.side] ?? def.tiles.side);
