199:   const chunk = { ...data, group: null, cx: next.cx, cz: next.cz };
200:   state.chunks.set(next.key, chunk);
201:   for (let z = 0; z < 16; z++) for (let x = 0; x < 16; x++) {
202:     const wx = next.cx * 16 + x, wz = next.cz * 16 + z;
203:     const startY = chunk.heights[z * 16 + x] + 1;
204:     for (let y = startY; y < WORLD_HEIGHT; y++) {
