312: function findTarget() {
313:   const direction = new THREE.Vector3();
314:   camera.getWorldDirection(direction);
315:   let x = Math.floor(camera.position.x), y = Math.floor(camera.position.y), z = Math.floor(camera.position.z);
316:   const stepX = Math.sign(direction.x), stepY = Math.sign(direction.y), stepZ = Math.sign(direction.z);
317:   const deltaX = stepX ? Math.abs(1 / direction.x) : Infinity;
318:   const deltaY = stepY ? Math.abs(1 / direction.y) : Infinity;
319:   const deltaZ = stepZ ? Math.abs(1 / direction.z) : Infinity;
320:   let maxX = stepX > 0 ? (x + 1 - camera.position.x) * deltaX : (camera.position.x - x) * deltaX;
321:   let maxY = stepY > 0 ? (y + 1 - camera.position.y) * deltaY : (camera.position.y - y) * deltaY;
322:   let maxZ = stepZ > 0 ? (z + 1 - camera.position.z) * deltaZ : (camera.position.z - z) * deltaZ;
323:   let previous = null;
324:   for (let distance = 0; distance <= 7; distance++) {
325:     const id = getBlock(x, y, z);
326:     if (id && id !== BLOCK_IDS.water && !getBlockDef(id).plant) return { x, y, z, id, previous };
327:     previous = { x, y, z };
328:     if (maxX < maxY && maxX < maxZ) { x += stepX; distance = maxX; maxX += deltaX; }
329:     else if (maxY < maxZ) { y += stepY; distance = maxY; maxY += deltaY; }
330:     else { z += stepZ; distance = maxZ; maxZ += deltaZ; }
331:   }
332:   return null;
333: }
