421: function movePlayer(dt) {
422:   const forward = (state.keys.has('KeyW') || state.move.z < -0.15 ? 1 : 0) - (state.keys.has('KeyS') || state.move.z > 0.15 ? 1 : 0);
423:   const strafe = (state.keys.has('KeyD') || state.move.x > 0.15 ? 1 : 0) - (state.keys.has('KeyA') || state.move.x < -0.15 ? 1 : 0);
424:   const sprint = state.keys.has('ShiftLeft') || state.keys.has('ShiftRight');
425:   const speed = state.flying ? (sprint ? 12 : 7) : (sprint ? 7.3 : 4.7);
426:   const length = Math.hypot(forward, strafe) || 1;
427:   const dx = (Math.sin(state.yaw) * forward + Math.cos(state.yaw) * strafe) * speed * dt / length;
428:   const dz = (-Math.cos(state.yaw) * forward + Math.sin(state.yaw) * strafe) * speed * dt / length;
429:   const nx = state.x + dx;
